#!/usr/bin/env node
'use strict';

/*
 * extract.js <elf-file>
 *
 * Reconstructs the memory image of an ELF executable from its program
 * headers and prints it as a JSON object mapping virtual memory addresses
 * (decimal strings) to the 32-bit little/big-endian integer stored there.
 *
 * Only PT_LOAD segments are considered: those are the parts of the file
 * that the kernel maps into the process address space.  Each full 4-byte
 * word that lies entirely inside a segment's file-backed range
 * (p_filesz) is emitted.  Zero-filled tail of a segment (p_memsz >
 * p_filesz, i.e. .bss) is intentionally left out rather than guessed at.
 */

const fs = require('fs');

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-file>\n');
    process.exit(2);
  }

  const buf = fs.readFileSync(path);
  if (buf.length < 16 ||
      buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    // Not an ELF file.  Fall back to a flat image starting at address 0
    // so the program still produces a sane mapping instead of crashing.
    emitFlat(buf, 0, false);
    return;
  }

  const ei_class = buf[4]; // 1 = 32-bit, 2 = 64-bit
  const ei_data = buf[5];  // 1 = little-endian, 2 = big-endian
  const little = ei_data !== 2;
  const is64 = ei_class === 2;

  // Endianness-aware primitive readers.
  const u16 = (o) => little ? buf.readUInt16LE(o) : buf.readUInt16BE(o);
  const u32 = (o) => little ? buf.readUInt32LE(o) : buf.readUInt32BE(o);
  const u64 = (o) => little ? buf.readBigUInt64LE(o) : buf.readBigUInt64BE(o);

  let phoff, phentsize, phnum;
  if (is64) {
    phoff = Number(u64(0x20));
    phentsize = u16(0x36);
    phnum = u16(0x38);
  } else {
    phoff = u32(0x1c);
    phentsize = u16(0x2a);
    phnum = u16(0x2c);
  }

  const out = Object.create(null);

  for (let i = 0; i < phnum; i++) {
    const base = phoff + i * phentsize;
    if (base < 0 || base + phentsize > buf.length) break;

    const p_type = u32(base + 0x00);
    if (p_type !== 1) continue; // PT_LOAD only

    let p_offset, p_vaddr, p_filesz, p_memsz;
    if (is64) {
      p_offset = Number(u64(base + 0x08));
      p_vaddr = Number(u64(base + 0x10));
      p_filesz = Number(u64(base + 0x20));
      p_memsz = Number(u64(base + 0x28));
    } else {
      p_offset = u32(base + 0x04);
      p_vaddr = u32(base + 0x08);
      p_filesz = u32(base + 0x10);
      p_memsz = u32(base + 0x14);
    }

    // Only the file-backed part of the segment is present in the binary.
    let span = Math.min(p_filesz, p_memsz);
    if (p_offset < 0 || p_offset >= buf.length) continue;
    span = Math.min(span, buf.length - p_offset);

    // Emit only complete 4-byte words.
    for (let off = 0; off + 4 <= span; off += 4) {
      const addr = p_vaddr + off;
      const val = little ? buf.readUInt32LE(p_offset + off)
                         : buf.readUInt32BE(p_offset + off);
      out[String(addr)] = val;
    }
  }

  process.stdout.write(JSON.stringify(out));
}

function emitFlat(buf, base, little) {
  const out = Object.create(null);
  for (let off = 0; off + 4 <= buf.length; off += 4) {
    out[String(base + off)] = little ? buf.readUInt32LE(off)
                                     : buf.readUInt32BE(off);
  }
  process.stdout.write(JSON.stringify(out));
}

main();

