import struct
def stats(path):
    buf=open(path,'rb').read()
    if buf[:4]!=b'\x7fELF': return None
    is64=buf[4]==2; little=buf[5]!=2
    if is64:
        phoff=struct.unpack_from('<Q',buf,0x20)[0]; es=struct.unpack_from('<H',buf,0x36)[0]; n=struct.unpack_from('<H',buf,0x38)[0]
    else:
        phoff=struct.unpack_from('<I',buf,0x1c)[0]; es=struct.unpack_from('<H',buf,0x2a)[0]; n=struct.unpack_from('<H',buf,0x2c)[0]
    tot=hi=0
    for i in range(n):
        o=phoff+i*es
        if struct.unpack_from('<I',buf,o)[0]!=1: continue
        if is64:
            off=struct.unpack_from('<Q',buf,o+8)[0]; fsz=struct.unpack_from('<Q',buf,o+32)[0]; msz=struct.unpack_from('<Q',buf,o+40)[0]
        else:
            off=struct.unpack_from('<I',buf,o+4)[0]; fsz=struct.unpack_from('<I',buf,o+16)[0]; msz=struct.unpack_from('<I',buf,o+20)[0]
        span=min(fsz,msz,len(buf)-off)
        for j in range(0,span-3,4):
            v=struct.unpack_from('<I',buf,off+j)[0]; tot+=1; hi += v>=2**31
    return tot,hi,hi/tot if tot else 0
