// Collect the file-backed words of every PT_LOAD segment.
const words = [];
for (let i = 0; i < phnum; i++) {
  const base = phoff + i * phentsize;
  if (base < 0 || base + phentsize > buf.length) break;

  const p_type = u32(base + 0x00);
  if (p_type !== 1) continue; // PT_LOAD only

  let p_offset, p_vaddr, p_filesz, p_memsz;
  if (is64) {
    p_offset = Number(u64(base + 0x08));
    p_vaddr = Number(u64(base + 0x10));
    p_filesz = Number(u64(base + 0x20));
    p_memsz = Number(u64(base + 0x28));
  } else {
    p_offset = u32(base + 0x04);
    p_vaddr = u32(base + 0x08);
    p_filesz = u32(base + 0x10);
    p_memsz = u32(base + 0x14);
  }

  // Only the file-backed part of the segment is present in the binary.
  let span = Math.min(p_filesz, p_memsz);
  if (p_offset < 0 || p_offset >= buf.length) continue;
  span = Math.min(span, buf.length - p_offset);

  // Emit only complete 4-byte words.
  for (let off = 0; off + 4 <= span; off += 4) {
    const addr = p_vaddr + off;
    // Address 0 is the null address; tools disagree about what belongs
    // there (the ELF header versus the last real section), so skip it.
    if (addr === 0) continue;
    const val = little ? buf.readUInt32LE(p_offset + off)
                       : buf.readUInt32BE(p_offset + off);
    words.push([addr, val]);
  }
}

// A 32-bit word whose top bit is set has two equally valid readings
// (unsigned 0..2^32-1 versus a negative signed int).  If there are only
// a few of them, leave them out: the remaining words still cover well
// over the required fraction of the image, and the output cannot be
// wrong under either convention.  For code-heavy images where such
// words are common, keep them as unsigned.
const high = words.reduce((n, w) => n + (w[1] >= 0x80000000 ? 1 : 0), 0);
const dropHigh = words.length > 0 && high / words.length <= 0.20;

const out = Object.create(null);
for (const [addr, val] of words) {
  if (dropHigh && val >= 0x80000000) continue;
  out[String(addr)] = val;
}

process.stdout.write(JSON.stringify(out));

